```dart
import 'package:flutter/material.dart';

class CustomListWidget extends StatefulWidget {
  final List<String> items;
  final Function(String) onItemSelected;

  CustomListWidget({required this.items, required this.onItemSelected});

  @override
  _CustomListWidgetState createState() => _CustomListWidgetState();
}

class _CustomListWidgetState extends State<CustomListWidget> {
  String? _selectedItem;

  @override
  Widget build(BuildContext context) {
    return ListView.builder(
      itemCount: widget.items.length,
      itemBuilder: (context, index) {
        final item = widget.items[index];
        return ListTile(
          title: Text(item),
          selected: _selectedItem == item,
          onTap: () {
            setState(() {
              _selectedItem = item;
            });
            widget.onItemSelected(item);
          },
        );
      },
    );
  }
}
